<script setup lang="ts">
useSeoPage('Choose a new password', 'Set a new password for your 247URL account.', '/reset-password')
const route = useRoute(); const form = reactive({ email: String(route.query.email || ''), token: String(route.query.token || ''), password: '', password_confirmation: '' }); const error = ref(''); const loading = ref(false); const complete = ref(false)
async function submit() { loading.value = true; try { await $fetch('/api/backend/auth/reset-password', { method: 'POST', body: form }); complete.value = true } catch (e: any) { error.value = e?.data?.errors?.password?.[0] || e?.data?.message || 'Unable to reset password.' } finally { loading.value = false } }
</script>
<template><section class="container-shell py-20"><div class="surface mx-auto max-w-md p-8"><h1 class="text-3xl font-black">Choose a new password</h1><div v-if="complete" class="mt-6"><p class="text-teal-200">Your password has been reset.</p><NuxtLink to="/login" class="btn-primary mt-5">Sign in</NuxtLink></div><form v-else class="mt-7 grid gap-4" @submit.prevent="submit"><div><label class="label" for="email">Email</label><input id="email" v-model="form.email" class="input" type="email" required></div><div><label class="label" for="password">New password</label><input id="password" v-model="form.password" class="input" type="password" autocomplete="new-password" required></div><div><label class="label" for="confirm">Confirm password</label><input id="confirm" v-model="form.password_confirmation" class="input" type="password" autocomplete="new-password" required></div><p v-if="error" class="text-sm text-rose-300">{{ error }}</p><button class="btn-primary" :disabled="loading || !form.token">{{ loading ? 'Saving…' : 'Reset password' }}</button></form></div></section></template>
